lemma modulusOfContinuity_bddAbove (f : ℝ → ℝ) (a b η : ℝ)
    (hf : ContinuousOn f (Icc a b)) :
    BddAbove {|f x - f y| | (x ∈ Icc a b) (y ∈ Icc a b) (_ : |x - y| ≤ η)}

